const titleEl = element;
if (titleEl.textContent.trim() !== 'More from YouTube') return;
const section = titleEl.closest('ytd-guide-section-renderer');
if (!section) return;
const parent = section.parentElement;
if (!parent || !parent.firstChild) return;
if (parent.firstChild === section) return;
parent.insertBefore(section, parent.firstChild);
